import * as z from "zod/v4";
import { registerContinuation, registerContinuationChannel, } from "../../internal/continuation-registration.js";
import { createResourceChannel } from "../../internal/resource-channel.js";
import { CHECKPOINT_CREATED_EVENT_TYPE, } from "./types.js";
const checkpointResourceSchema = z
    .object({
    name: z.string().min(1),
    deployment: z.string().min(1),
    runKey: z.string().min(1),
    evidenceSummary: z.string().min(1),
    planRevision: z.string().optional(),
    createTime: z.string().min(1).optional(),
    description: z.string().optional(),
    clear: z.object({}).passthrough().optional(),
    issues: z
        .object({ title: z.string().min(1) })
        .passthrough()
        .optional(),
    inconclusive: z.object({}).passthrough().optional(),
    deferred: z
        .object({ reason: z.string().min(1) })
        .passthrough()
        .optional(),
})
    .passthrough()
    .refine((checkpoint) => [checkpoint.clear, checkpoint.issues, checkpoint.inconclusive, checkpoint.deferred].filter((arm) => arm !== undefined).length === 1, { message: "checkpoint must have exactly one result arm" });
const checkpointCreatedEventSchema = z.object({
    eventId: z.string().min(1),
    eventType: z.literal(CHECKPOINT_CREATED_EVENT_TYPE),
    teamId: z.string().min(1),
    occurredAtMs: z.number().int().nonnegative(),
    checkpoint: checkpointResourceSchema,
});
const pack = createResourceChannel({
    kind: "change_monitors",
    eventTypes: [CHECKPOINT_CREATED_EVENT_TYPE],
    eventSchema: checkpointCreatedEventSchema,
    replayDescription: "Replay a Change Monitor checkpoint-created event.",
    invalidError: "invalid change-monitor checkpoint event",
});
export function changeMonitorsChannel(options) {
    return pack.channel(options);
}
export function getChangeMonitorsChannelOptions(definition) {
    return pack.getOptions(definition);
}
registerContinuationChannel({
    kind: "change_monitors",
    getOptions: getChangeMonitorsChannelOptions,
    usesDeclaredEvents: true,
});
registerContinuation({
    type: "change-monitor-checkpoint",
    kind: "change_monitors",
    events: [CHECKPOINT_CREATED_EVENT_TYPE],
    format: "change_monitors:{checkpointName}",
    selector: "change_monitors.checkpoint/v2",
});
